var removeDuplicates = function(s) {
    let stack = []; // Initialize an empty stack

    // Iterate through each character in the string
    for (let char of s) {
        // If the stack is not empty and the current character is equal to the top element of the stack
        if (stack.length > 0 && char === stack[stack.length - 1]) {
            stack.pop(); // Remove the adjacent duplicate by popping the top element
        } else {
            stack.push(char); // Push the current character onto the stack
        }
    }

    // Construct the final string by joining the characters in the stack
    return stack.join('');
};

